#!/usr/bin/env node
/**
 * Refuse to let private Gameplan data into the one repository that is actually
 * public.
 *
 * WHY HERE, WHEN PRO-SCOUT ALREADY HAS ONE
 *   pro-scout's copy of this guard opens by saying "Pro-Scout is intended to
 *   become public." Intended. pro-scout is private today; this repository is
 *   not, and it is the end of the chain gameplan -> pro-scout -> pro-scout-ui.
 *   Every manifest under data/ is generated by pro-scout and copied here, so
 *   the leak that matters travels in exactly that direction and lands on a
 *   page anybody can read.
 *
 *   The guard existed on the private half of the pipe and not the published
 *   one.
 *
 * WHAT WAS ALREADY CHECKED, AND WHAT WAS NOT
 *   test/player-table.test.mjs scans data/player-manifest.json for the
 *   substrings "kcffl", "owner-" and "franchise_id". That is a real check and
 *   it stays -- it catches a lowercase mention anywhere in that file, which the
 *   patterns below deliberately do not. What it does not do is look at any
 *   other file. data/team-manifest.json and the rest of the tree were never
 *   read. This scans every tracked file.
 *
 * WHAT IT DISTINGUISHES
 *   A contract may NAME an owner field; that is a shape, and shapes are not
 *   secrets. contracts/ carries provider schemas that have every right to
 *   declare owner_id with a pattern. What must never appear is an owner
 *   IDENTIFIER, a franchise identifier, or a KCFFL valuation -- those are data,
 *   and data is what leaks.
 *
 * WHAT IT DOES NOT CLAIM
 *   It catches identifiers and valuations that are recognisable. It cannot
 *   recognise a leak arriving with no distinguishing marks -- and the sharpest
 *   example of that is already pinned by another test in this repo:
 *   test/player-table.test.mjs asserts the available rows stay alphabetical,
 *   because an ordering derived from league judgement publishes draft strategy
 *   through selection alone, with no forbidden string for any scanner to find.
 *   A green result here is not proof that nothing private is present.
 *
 *   node scripts/check-public-boundary.mjs
 */
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(fileURLToPath(new URL("..", import.meta.url)));

// Identifiers. Forbidden everywhere, including inside vendored contracts: a
// schema has no reason to carry a real owner or franchise id, and an example
// that does is a leak wearing documentation's clothes.
const FORBIDDEN_IDENTIFIERS = [
  [/"OWNER-[0-9A-Z][0-9A-Z-]*"/, "a KCFFL owner identifier"],
  [/KCFFL-F-(?:\d{2}|H\d{2})/, "a KCFFL franchise identifier"],
  [/FRANCHISE:KCFFL:/, "a pre-migration KCFFL franchise identifier"],
  [/ASSET:KCFFL:/, "a KCFFL asset identifier"],
];

// League valuations and judgments. Allowed to be named in a contract and
// described in the two files that state this repository's rules; never carried
// as data anywhere else.
const FORBIDDEN_JUDGMENTS = [
  [/"kcffl_points(?:_by_season)?"\s*:/, "KCFFL scoring applied to a player"],
  [/"value_over_replacement(?:_points)?"\s*:/, "a draft-board valuation"],
  [/"keeper_(?:value|decision|slot|cost)"\s*:/, "a keeper judgment"],
  [/"franchise_mode"\s*:/, "franchise mode state"],
  [/"owner_objective/, "owner objective state"],
];

// Where a JUDGMENT may be NAMED rather than carried. Judgments only: an
// identifier is refused everywhere in this repository, including here.
//
// pro-scout exempts contracts/, schema/ and docs/ and, since its #45, exempts
// them for IDENTIFIERS too -- because neither it nor Gameplan will ever be
// public. This repository is public, so that exemption stops at the boundary
// and identifiers stay refused in contracts/. The divergence is deliberate;
// test/public-boundary.test.mjs states why at the case that guards it.
//
// This repository has no schema/ or docs/, and the two files that describe what
// it forbids sit at the root.
const SHAPE_PATHS = ["contracts/", "README.md", "CLAUDE.md"];

// This file names every pattern it forbids, and its test plants them
// deliberately.
// These two name every pattern they forbid, in literal text, so scanning them
// would report them forever. Nothing else belongs here: an exclusion is a hole,
// and whatever is later written into an excluded file is exempt from this check
// permanently. Exported so test/public-boundary.test.mjs can require each entry
// to prove it earns its place rather than merely being listed.
export const SELF = ["scripts/check-public-boundary.mjs", "test/public-boundary.test.mjs"];

function trackedFiles() {
  const out = execFileSync("git", ["ls-files", "-z"], { cwd: ROOT, encoding: "utf8" });
  return out.split("\0").filter(Boolean);
}

export function scanContent(relativePath, content) {
  const findings = [];
  const isShape = SHAPE_PATHS.some((prefix) => relativePath.startsWith(prefix));

  for (const [pattern, description] of FORBIDDEN_IDENTIFIERS) {
    const match = content.match(pattern);
    if (match) findings.push({ relativePath, description, sample: match[0].slice(0, 60) });
  }
  if (!isShape) {
    for (const [pattern, description] of FORBIDDEN_JUDGMENTS) {
      const match = content.match(pattern);
      if (match) findings.push({ relativePath, description, sample: match[0].slice(0, 60) });
    }
  }
  return findings;
}

export function scanRepository(files, read, tally = null) {
  const findings = [];
  let inspected = 0;
  let binary = 0;
  let excluded = 0;
  for (const relativePath of files) {
    if (SELF.includes(relativePath)) {
      excluded += 1;
      continue;
    }
    let content;
    try {
      content = read(relativePath);
    } catch (error) {
      // A file that cannot be read is a file that was not checked, and
      // reporting the scan clean would be a green result that proves nothing.
      findings.push({
        relativePath,
        description: "could not be inspected, so it was not checked",
        sample: String(error && error.message ? error.message : error).slice(0, 60),
      });
      continue;
    }
    if (content.includes("\0")) {
      // A LITERAL NUL HERE IS WHY THIS IS COUNTED NOW.
      // This very line used to hold a raw NUL byte instead of the escape, which
      // made check-public-boundary.mjs itself binary -- unreviewable in a diff,
      // and skipped by this very branch had SELF not happened to cover it. One
      // stray NUL is all it takes for a tracked file to stop being scanned, and
      // a bare continue said nothing when that happened. Counting is what turns
      // "scanned clean" into a claim with a denominator.
      binary += 1;
      continue;
    }
    inspected += 1;
    findings.push(...scanContent(relativePath, content));
  }
  if (tally) Object.assign(tally, { inspected, binary, excluded });
  return findings;
}

function main() {
  const files = trackedFiles();
  const tally = {};
  const findings = scanRepository(
    files,
    (relative) => fs.readFileSync(path.join(ROOT, relative), "utf8"),
    tally,
  );

  if (findings.length > 0) {
    console.error("private Gameplan data found in the public UI:\n");
    for (const finding of findings) {
      console.error(`  ${finding.relativePath}`);
      console.error(`      ${finding.description}: ${finding.sample}`);
    }
    console.error(
      "\nThis repository is public. Fix it upstream in pro-scout and re-sync, or remove it.",
    );
    return 1;
  }
  console.log(
    `public boundary OK: ${tally.inspected} of ${files.length} tracked files inspected`
      + ` (${tally.binary} binary, ${tally.excluded} self-excluded),`
      + " no owner or league data",
  );
  return 0;
}

const invokedDirectly = process.argv[1]
  && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url));
if (invokedDirectly) process.exit(main());
